bl-py.text:
# Match Stripe payouts to invoices
import csv

def reconcile(payouts, invoices):
    paid = {p['invoice'] for p in payouts}
    # an invoice is settled when a payout names it
    return [i for i in invoices if i['id'] not in paid]

if __name__ == '__main__':
    print('31 invoices reconciled, 0 open')

cn-lawmatics-js.text:
// Small helpers the declarative part of connector.toml cannot express.
// Runs in a sandbox on the Space server. Network: api.lawmatics.example only.

export function contactFromRemote(remote) {
  return {
    name: [remote.first_name, remote.last_name].filter(Boolean).join(" "),
    email: (remote.email || "").toLowerCase(),
    stage: ({ new: "Lead", active: "Client", closed: "Past client" })[remote.status] || "Lead",
    updated_at: remote.updated_at,
  };
}

export function contactFromRemoteToRemote(local) {
  const [first_name, ...rest] = String(local.name || "").split(" ");
  return { first_name, last_name: rest.join(" "), email: local.email };
}

